pub fn reverse(v: &mut Vec<u64>) {
    let mut i: usize = 0;
    let mut j: usize = v.len();

    // Swap symmetric elements moving inward.
    // Works for empty and single-element vectors as well.
    while i < j {
        j -= 1;
        if i >= j {
            break;
        }
        v.swap(i, j);
        i += 1;
    }
}

